def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # If we're past the end, we're done
        if i == n:
            break

        # Quoted field
        if line[i] == '"':
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Must be followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        # Consume the comma if present
                        if i < n:
                            i += 1
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            # Consume the comma if present
            if i < n:
                i += 1

    return fields

